class Solution {
  public int numTriplets(int[] nums1, int[] nums2) {
    return count(nums1, nums2) + count(nums2, nums1);
  }

  // triplets (i, j, k) with source[i]^2 == other[j] * other[k] and j < k
  private int count(int[] source, int[] other) {
    Map<Long, Integer> freq = new HashMap<>();
    for (int x : other) freq.merge((long) x, 1, Integer::sum);
    int total = 0;
    for (int s : source) {
      long square = (long) s * s;
      for (Map.Entry<Long, Integer> e : freq.entrySet()) {
        long a = e.getKey();
        if (square % a != 0) continue;
        long b = square / a;
        if (a < b) {
          Integer other2 = freq.get(b);
          if (other2 != null) total += e.getValue() * other2;
        } else if (a == b) {
          total += e.getValue() * (e.getValue() - 1) / 2;
        }
      }
    }
    return total;
  }
}
